// The structural checks of a code release over its captured files: required and generated files, the reference
// scan of scripts and stylesheets, fonts and images, the descriptor, and query.yaml, access.yaml and site.yaml.
// Ported from the engine's tests (behaviour parity); the engine's string problems are diagnostics here.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';

import { checkCodeRelease } from '@foliwake/site-check';
import { isCapturedInput, isCodeInput } from '@foliwake/site-check/formats/layout';

const NOTE = { fields: [{ name: 'text', type: 'text' }] };
const LOADER = [
  "const codeBase = new URL('../', import.meta.url);",
  "const assetUrl = (name, ext) => new URL(`components/${name}/${name}.${ext}`, codeBase);",
  "export const load = (name) => import(assetUrl(name, 'js').href);",
  '',
].join('\n');

/** Captured files: path → text or bytes; null leaves a file out. */
function filesOf(entries) {
  const files = new Map();
  for (const [file, value] of Object.entries(entries)) {
    if (value !== null) files.set(file, Buffer.isBuffer(value) ? value : Buffer.from(value));
  }
  return files;
}

/** A minimal valid release (a loader, a stylesheet, one block), with `changes` on top. */
function release(changes = {}) {
  return filesOf({
    'scripts/components.js': LOADER,
    'styles/styles.css': 'body { margin: 0; }\n',
    'components/note/note.json': JSON.stringify(NOTE),
    ...changes,
  });
}

/** A release whose block script imports `./extra.js` with `source`. */
function withExtra(source) {
  return release({
    'components/note/note.js': "import './extra.js';\nexport default function decorate() {}\n",
    'components/note/extra.js': `${source}\n`,
  });
}

const errorsOf = (result) => result.diagnostics.filter((d) => d.severity === 'error');
const errorText = (result) => errorsOf(result).map((d) => `${d.code} ${d.file}: ${d.message}`).join('\n');
/** A regular expression that matches `text` literally. */
const literal = (text) => new RegExp(text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&'));

describe('required and generated files', () => {
  test('the minimal release is accepted', async () => {
    assert.deepEqual(errorsOf(await checkCodeRelease(release())), []);
  });

  test('a release without the loader or the page stylesheet is refused', async () => {
    const result = await checkCodeRelease(release({ 'scripts/components.js': null, 'styles/styles.css': null }));
    const required = result.diagnostics.filter((d) => d.code === 'CODE_FILE_REQUIRED');
    assert.deepEqual(
      required.map((d) => [d.file, d.severity]),
      [
        ['scripts/components.js', 'error'],
        ['styles/styles.css', 'error'],
      ],
    );
    assert.equal(required[0].message, 'Every code release needs scripts/components.js; it is missing.');
  });

  test('a generated file given as an input refuses the release', async () => {
    for (const file of ['blocks.json', 'templates.json', 'blocks-catalog.json', 'shell.json']) {
      const result = await checkCodeRelease(release({ [file]: '{}' }));
      assert.match(errorText(result), literal(`CODE_FILE_GENERATED ${file}: ${file} is generated by the engine`), file);
      assert.equal(result.captured.includes(file), false, file);
    }
  });
});

describe('the reference scan of scripts and stylesheets', () => {
  const ESCAPING = {
    'template-literal dynamic import of another release':
      'export default async function decorate() { await import(`/code/cd_${"0".repeat(64)}/components/a/a.js`); }',
    'template-literal dynamic import of another origin':
      'export default async function decorate() { await import(`https://cdn.example.invalid/x.js`); }',
    'new URL escaping the release':
      'export default function decorate() { return new URL("../../../cd_other/x.js", import.meta.url); }',
  };
  for (const [name, source] of Object.entries(ESCAPING)) {
    test(`a ${name} is refused`, async () => {
      const result = await checkCodeRelease(withExtra(source));
      const errors = errorsOf(result);
      assert.ok(errors.length > 0, `release with a ${name} was accepted without any diagnostic`);
      assert.ok(errors.some((d) => d.file === 'components/note/extra.js'), errorText(result));
    });
  }

  test('in-release template literals and new URL references stay valid; so does a computed loader', async () => {
    const source = [
      'const name = "note";',
      'export const a = () => import(`./note.js`);',
      'export const b = () => import(`./${name}.js`);',
      'export const c = new URL("../../", import.meta.url);',
      'export const d = new URL("note.json", import.meta.url);',
      'export const e = new URL(`./${name}.css`, import.meta.url);',
    ].join('\n');
    assert.deepEqual(errorsOf(await checkCodeRelease(withExtra(source))), []);
    assert.deepEqual(errorsOf(await checkCodeRelease(release())), [], 'computed import, new URL("../")');
  });

  test('a missing or escaping in-release template literal is refused', async () => {
    const cases = [
      ['export const a = () => import(`./missing.js`);', /missing\.js.*not in the release/],
      ['export const a = () => import(`../../../${x}.js`);', /escapes the release directory/],
      ['export const a = () => import(`lib/${x}.js`);', /is not relative/],
      ['export const b = new URL("../../../../x.js", import.meta.url);', /escapes the release directory/],
      ['export const c = new URL(`//cdn.example.invalid/${x}`, import.meta.url);', /not relative/],
    ];
    for (const [source, pattern] of cases) {
      assert.match(errorText(await checkCodeRelease(withExtra(source))), pattern, source);
    }
  });

  for (const spec of ['.', '..']) {
    test(`new URL(${JSON.stringify(spec)}, import.meta.url) is a valid in-release directory reference`, async () => {
      const source = `export const dir = new URL(${JSON.stringify(spec)}, import.meta.url);`;
      assert.deepEqual(errorsOf(await checkCodeRelease(withExtra(source))), []);
    });
  }

  test('an interpolated template import whose static prefix escapes the release is refused', async () => {
    const source = 'export const load = (x) => import(`../../../cd_other/components/${x}.js`);';
    assert.match(errorText(await checkCodeRelease(withExtra(source))), /escapes the release directory/);
  });

  test('the message names the reference without the file; the file, line and column are set', async () => {
    const result = await checkCodeRelease(withExtra('const pad = 1;\nexport const a = () => import(`./missing.js`);'));
    const [missing] = result.diagnostics.filter((d) => d.code === 'CODE_REFERENCE_MISSING');
    assert.equal(missing.file, 'components/note/extra.js');
    assert.equal(
      missing.message,
      'reference "./missing.js" resolves to components/note/missing.js, which is not in the release',
    );
    assert.deepEqual([missing.line, missing.column], [2, 24]);
  });
});

describe('the bare `foliwake` import', () => {
  const withScript = (path, source) => checkCodeRelease(release({ [path]: source }));

  test('`foliwake` is the only bare import, and only in scripts', async () => {
    const kit = "import { defineBlock } from 'foliwake';\nexport default defineBlock('note', () => {});\n";
    assert.deepEqual(errorsOf(await withScript('components/note/note.js', kit)), []);
    const lodash = "import x from 'lodash';\nexport default function init() {}\n";
    const bare = await withScript('components/note/note.js', lodash);
    assert.match(errorText(bare), /"lodash" is not relative/);
    const css = await withScript('components/note/note.css', "@import 'foliwake';\n");
    assert.match(errorText(css), /"foliwake" is not relative/, 'only scripts may name the kit');
  });

  test('the block name is left to the loader: no static guess refuses a release', async () => {
    const accepted = [
      "import { defineBlock } from 'foliwake';\nexport default defineBlock('notes', () => {});\n",
      "import { defineBlock } from 'foliwake';\n" +
        "const help = \"Example: \\\nexport default defineBlock('quiz', () => {})\";\n" +
        "const init = defineBlock('note', () => help);\nexport default init;\n",
      "import { defineBlock } from 'foliwake';\n// example: defineBlock('quiz', …)\n" +
        "export default defineBlock('note', () => {});\n",
      "import { defineBlock } from 'foliwake';\n/*\nexport default defineBlock('quiz', () => {});\n*/\n" +
        "export default defineBlock('note', () => {});\n",
      "import { defineBlock } from 'foliwake';\nconst doc = `\nexport default defineBlock('quiz', () => {});\n`;\n" +
        "export default defineBlock('note', () => doc);\n",
      "import { defineBlock } from 'foliwake';\nconst help = \"defineBlock('quiz', …)\";\n" +
        "export default defineBlock('note', () => help);\n",
      "import { defineBlock } from 'foliwake';\nconst init = defineBlock('quiz', () => {});\nexport default init;\n",
      "/*\nexport default defineBlock('quiz', () => {});\n*/\nexport default function init() {}\n",
    ];
    for (const source of accepted) {
      const result = await withScript('components/note/note.js', source);
      assert.deepEqual(errorsOf(result), [], source);
    }
  });
});

describe('fonts and images', () => {
  const FONT = Buffer.from('wOF2 not really a font');
  const SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1 1"><rect width="1" height="1"/></svg>';
  const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const FONT_CSS =
    '@font-face { font-family: Site; src: url("./fonts/site.woff2") format("woff2"), ' +
    'url("./fonts/site.ttf?v=1#iefix") format("truetype"); }';
  const ASSETS = [
    'styles/fonts/site.woff2',
    'styles/fonts/site.ttf',
    'components/hero/icon.svg',
    'components/hero/bg.png',
  ];

  function withAssets(css) {
    return release({
      'styles/fonts/site.woff2': FONT,
      'styles/fonts/site.ttf': FONT,
      'components/hero/icon.svg': SVG,
      'components/hero/bg.png': PNG,
      'styles/notes.txt': 'not site code\n',
      'styles/styles.css': `body { margin: 0; }\n${css}\n`,
    });
  }

  test('fonts and images are captured and referenced from CSS; other file types stay out', async () => {
    const css = `${FONT_CSS}\n.hero { background: url("../components/hero/bg.png"); }`;
    const result = await checkCodeRelease(withAssets(css));
    assert.deepEqual(errorsOf(result), []);
    for (const file of ASSETS) assert.ok(result.captured.includes(file), `${file} is in the release`);
    assert.equal(result.captured.includes('styles/notes.txt'), false, 'other file types stay out');
  });

  test('a CSS reference to a font that is not in the release refuses the release, as for scripts', async () => {
    const css = '@font-face { font-family: Gone; src: url("./fonts/missing.woff2"); }';
    const result = await checkCodeRelease(withAssets(css));
    assert.match(errorText(result), /fonts\/missing\.woff2.*not in the release/);
  });

  test('one list decides capture: fonts and images in, other types and dot paths out', () => {
    const inside = [
      'styles/fonts/a.woff2', 'styles/fonts/a.woff', 'styles/fonts/a.ttf', 'styles/fonts/a.otf',
      'components/x/icon.svg', 'components/x/bg.png', 'components/x/a.jpg', 'components/x/a.jpeg',
      'components/x/a.webp', 'components/x/a.avif', 'components/x/a.gif',
      'scripts/a.js', 'styles/a.css', 'components/x/x.json',
    ];
    const outside = [
      'styles/notes.txt', 'styles/a.TTF', 'components/x/a.mp4', 'styles/.fonts/a.woff2',
      'styles/fonts/.a.woff2', 'content/a.png', 'a.woff2',
    ];
    for (const file of inside) assert.ok(isCodeInput(file), file);
    for (const file of outside) assert.ok(!isCodeInput(file), file);
  });

  test('example files are captured inputs; other Markdown is not', () => {
    assert.ok(isCapturedInput('components/note/note.example.md'));
    assert.ok(!isCapturedInput('components/note/README.md'));
    assert.ok(!isCapturedInput('content/index.md'));
  });
});

describe('the descriptor of the captured files', () => {
  const OLD = {
    htmlContract: 1,
    components: {
      hero: { css: false, js: false },
      accordion: { css: false, js: false },
      lesson: { css: false, js: false },
    },
  };
  const handWritten = (descriptor) =>
    filesOf({
      'scripts/components.js': 'export {};\n',
      'styles/styles.css': 'body{}\n',
      'components/components.json': JSON.stringify(descriptor),
    });

  test('an old frontend descriptor (no question) is still valid for a code release of its contract', async () => {
    assert.deepEqual(errorsOf(await checkCodeRelease(handWritten(OLD), { htmlContract: 1 })), []);
    const newer = await checkCodeRelease(handWritten(OLD));
    assert.equal(
      errorText(newer),
      'CODE_DESCRIPTOR_INVALID components/components.json: htmlContract is 1, but the generator produces version 2.',
    );
  });

  test('a declared stylesheet that is not captured refuses the release', async () => {
    const declared = { ...OLD, components: { ...OLD.components, hero: { css: true, js: false } } };
    const result = await checkCodeRelease(handWritten(declared));
    const isMissingHeroCss = (d) => d.code === 'CODE_ASSET_MISSING' && d.component === 'hero';
    assert.ok(errorsOf(result).some(isMissingHeroCss), errorText(result));
  });
});

describe('query.yaml, access.yaml and site.yaml', () => {
  const QUERY = `version: 1
indices:
  default:
    include: ["/**"]
    exclude: ["/fragments/**", "/drafts/**"]
    target: /query-index.json
    properties: [title, description, lang]
sitemap:
  source: default
`;

  test('a valid query.yaml is captured and read; other root files and nested ones are not', async () => {
    const result = await checkCodeRelease(
      release({ 'query.yaml': QUERY, 'other.yaml': 'x: 1\n', 'components/cfg/query.yaml': 'x: 1\n' }),
    );
    assert.deepEqual(errorsOf(result), []);
    assert.ok(result.captured.includes('query.yaml'));
    assert.equal(result.captured.includes('other.yaml'), false);
    assert.equal(result.captured.includes('components/cfg/query.yaml'), false);
    assert.deepEqual(
      result.query.indices.map((index) => index.name),
      ['default'],
    );
  });

  test('an invalid query.yaml refuses the release, with its position and field', async () => {
    const bad = QUERY.replace('target: /query-index.json', 'target: /code/x.json');
    const result = await checkCodeRelease(release({ 'query.yaml': bad }));
    const [problem] = errorsOf(result);
    assert.equal(problem.code, 'QUERY_CONFIG_INVALID');
    assert.equal(problem.file, 'query.yaml');
    assert.equal(problem.field, 'indices.default.target');
    assert.equal(problem.line, 6);
    assert.match(problem.message, /target "\/code\/x\.json" is under the reserved prefix \/code\//);
    assert.equal(result.query, null);
    const version = await checkCodeRelease(release({ 'query.yaml': QUERY.replace('version: 1', 'version: 2') }));
    assert.deepEqual(errorsOf(version).map((d) => [d.code, d.line, d.field]), [['QUERY_CONFIG_INVALID', 1, 'version']]);
  });

  test('an invalid access.yaml refuses the release', async () => {
    const result = await checkCodeRelease(release({ 'access.yaml': 'version: 1\nallow: ["/media/**"]\n' }));
    const [problem] = errorsOf(result);
    assert.equal(problem.code, 'ACCESS_CONFIG_INVALID');
    assert.equal(problem.file, 'access.yaml');
    assert.match(problem.message, /reserved prefix/);
    assert.equal(result.access, null);
    const valid = await checkCodeRelease(release({ 'access.yaml': 'version: 1\nallow: ["/about"]\n' }));
    assert.deepEqual(errorsOf(valid), []);
    assert.notEqual(valid.access, null);
  });

  test('an invalid site.yaml refuses the release; a valid one gives its default', async () => {
    const refused = await checkCodeRelease(release({ 'site.yaml': 'version: 1\nauthoring: blocks-v3\ntheme: dark\n' }));
    assert.match(errorText(refused), /SITE_CONFIG_INVALID site\.yaml.*theme/);
    const valid = await checkCodeRelease(release({ 'site.yaml': 'version: 1\nauthoring: blocks-v3\n' }));
    assert.deepEqual(errorsOf(valid), []);
    assert.ok(valid.captured.includes('site.yaml'));
    assert.equal(valid.siteCode.authoringDefault, 'blocks-v3');
  });

});
